build.unitScript:
test("start 2026-01-31 for 3 payments clamps February to the 28th and April to the 30th and returns to the 31st in March", () => {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-31", count: 3 }), ["2026-02-28", "2026-03-31", "2026-04-30"]);
});
test("start 2027-12-31 for 3 payments rolls into 2028 and uses February 29 because 2028 is a leap year", () => {
  assert.deepEqual(code.dueDates({ startDate: "2027-12-31", count: 3 }), ["2028-01-31", "2028-02-29", "2028-03-31"]);
});
test("start 2026-01-15 for 2 payments keeps the 15th with no adjustment", () => {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-15", count: 2 }), ["2026-02-15", "2026-03-15"]);
});
test("start 2026-11-30 for 3 payments crosses the year end and clamps February 2027 to the 28th", () => {
  assert.deepEqual(code.dueDates({ startDate: "2026-11-30", count: 3 }), ["2026-12-30", "2027-01-30", "2027-02-28"]);
});
test("year 2100 is not a leap year so February 2100 ends on the 28th and March goes back to the 29th", () => {
  assert.deepEqual(code.dueDates({ startDate: "2100-01-29", count: 2 }), ["2100-02-28", "2100-03-29"]);
});
test("a full year of payments from 2026-01-31 returns 12 dates and every month goes back to the original day where it exists", () => {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-31", count: 12 }), ["2026-02-28", "2026-03-31", "2026-04-30", "2026-05-31", "2026-06-30", "2026-07-31", "2026-08-31", "2026-09-30", "2026-10-31", "2026-11-30", "2026-12-31", "2027-01-31"]);
});

build.testScript:
test("day 31 in a non-leap year uses February 28, returns to 31 in March, and uses April 30", function() {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-31", count: 3 }), ["2026-02-28", "2026-03-31", "2026-04-30"]);
});
test("day 31 from December uses January 31, leap February 29, and March 31", function() {
  assert.deepEqual(code.dueDates({ startDate: "2027-12-31", count: 3 }), ["2028-01-31", "2028-02-29", "2028-03-31"]);
});
test("day 15 exists every month so no day is adjusted", function() {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-15", count: 2 }), ["2026-02-15", "2026-03-15"]);
});
test("a count of one returns only the shortened February due date", function() {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-31", count: 1 }), ["2026-02-28"]);
});
test("the first of the month exists in every target month", function() {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-01", count: 3 }), ["2026-02-01", "2026-03-01", "2026-04-01"]);
});
test("day 28 exists in non-leap February so later months stay on 28", function() {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-28", count: 3 }), ["2026-02-28", "2026-03-28", "2026-04-28"]);
});
test("day 29 missing in non-leap February uses 28 then returns to 29", function() {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-29", count: 3 }), ["2026-02-28", "2026-03-29", "2026-04-29"]);
});
test("day 29 exists in leap February so later months stay on 29", function() {
  assert.deepEqual(code.dueDates({ startDate: "2028-01-29", count: 3 }), ["2028-02-29", "2028-03-29", "2028-04-29"]);
});
test("day 30 missing in non-leap February uses 28 then returns to 30 not month end", function() {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-30", count: 4 }), ["2026-02-28", "2026-03-30", "2026-04-30", "2026-05-30"]);
});
test("day 30 missing in leap February uses 29 then returns to 30", function() {
  assert.deepEqual(code.dueDates({ startDate: "2028-01-30", count: 3 }), ["2028-02-29", "2028-03-30", "2028-04-30"]);
});
test("leap February 29 then March 31 April 30 and May returns to 31", function() {
  assert.deepEqual(code.dueDates({ startDate: "2028-01-31", count: 4 }), ["2028-02-29", "2028-03-31", "2028-04-30", "2028-05-31"]);
});
test("shortened April 30 then May 31 then shortened June 30", function() {
  assert.deepEqual(code.dueDates({ startDate: "2026-03-31", count: 3 }), ["2026-04-30", "2026-05-31", "2026-06-30"]);
});
test("December 31 rolls to January 31 then non-leap February 28 then March 31", function() {
  assert.deepEqual(code.dueDates({ startDate: "2025-12-31", count: 3 }), ["2026-01-31", "2026-02-28", "2026-03-31"]);
});
test("the first from December rolls to January 1 then February 1 of the next year", function() {
  assert.deepEqual(code.dueDates({ startDate: "2026-12-01", count: 2 }), ["2027-01-01", "2027-02-01"]);
});
test("thirteen payments from day 15 cross the year boundary without adjustment", function() {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-15", count: 13 }), ["2026-02-15", "2026-03-15", "2026-04-15", "2026-05-15", "2026-06-15", "2026-07-15", "2026-08-15", "2026-09-15", "2026-10-15", "2026-11-15", "2026-12-15", "2027-01-15", "2027-02-15"]);
});
test("start on leap day shortens the next non-leap February then restores day 29", function() {
  assert.deepEqual(code.dueDates({ startDate: "2028-02-29", count: 13 }), ["2028-03-29", "2028-04-29", "2028-05-29", "2028-06-29", "2028-07-29", "2028-08-29", "2028-09-29", "2028-10-29", "2028-11-29", "2028-12-29", "2029-01-29", "2029-02-28", "2029-03-29"]);
});

